// Reads AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET, AUTH0_SECRET and APP_BASE_URL
export const auth0 = new Auth0Client();
import { auth0 } from "./auth0";
import { personForSession, type Person } from "./vault";

// The people rows (one per vault) for whoever is signed in
export async function currentPeople(): Promise<Person[]> {
  const session = await auth0.getSession();
  if (!session?.user) return [];
  return personForSession({ sub: session.user.sub, email: session.user.email, email_verified: session.user.email_verified as boolean | undefined });
}
// What the switch looks like right now, for the timeline page.
import { sql } from "./db";
import { getPeople, getSwitch } from "./vault";

export async function vaultStatus(vaultId: string) {
  const [s, people, approvals, audit, checkins] = await Promise.all([
    getSwitch(vaultId),
    getPeople(vaultId),
    sql`select person_id, round, status, sent_at, decided_at from approvals where vault_id = ${vaultId} order by round desc, sent_at`,
    sql`select id, at, actor, action, detail from audit_log where vault_id = ${vaultId} order by id desc limit 50`,
    sql`select id, kind, sent_at, answered_at, line from checkins where vault_id = ${vaultId} order by sent_at desc limit 20`,
  ]);
  // Approvals only mean something while confirming, or as the record of a release
  const current = s.state === "confirming" || s.state === "released" ? approvals.filter((a) => a.round === s.round) : [];
  return {
    state: s.state,
    switch: {
      every_seconds: s.every_seconds,
      miss_limit: s.miss_limit,
      grace_seconds: s.grace_seconds,
      missed_count: s.missed_count,
      last_answer_at: s.last_answer_at,
      last_ping_at: s.last_ping_at,
      last_chance_at: s.last_chance_at,
      released_at: s.released_at,
      round: s.round,
    },
    people: people.map((p) => ({ id: p.id, role: p.role, name: p.name, relation: p.relation, linked: !!p.auth0_sub })),
    approvals: current,
    checkins,
    audit,
  };
}
// The public demo vault: no sign-up. Visitors play the owner and both trusted people.
import { sql } from "./db";
import { getVault, type Vault } from "./vault";

export async function demoVault(): Promise<Vault> {
  const v = await getVault("demo");
  if (!v) throw new Error("demo vault missing: run bun run seed");
  return v;
}

export async function demoPerson(vaultId: string, personId: unknown) {
  if (typeof personId !== "string") return null;
  const [p] = await sql`select id, role, name from people where vault_id = ${vaultId} and id = ${personId}::uuid`.catch(() => []);
  return p ?? null;
}

// Keeps the free Groq quota alive when the demo link gets shared around
export async function demoQuestionsLastHour(vaultId: string) {
  const [r] = await sql`select count(*)::int as n from questions where vault_id = ${vaultId} and created_at > now() - interval '1 hour'`;
  return r.n as number;
}
