export type Vault = { id: string; slug: string; owner_name: string; is_demo: boolean };
export type Person = {
  id: string;
  vault_id: string;
  role: "owner" | "trusted";
  name: string;
  relation: string;
  email: string;
  auth0_sub: string | null;
};
export type SwitchState = "alive" | "missed" | "confirming" | "released";
export type SwitchRow = {
  vault_id: string;
  state: SwitchState;
  every_seconds: number;
  miss_limit: number;
  grace_seconds: number;
  last_answer_at: Date;
  last_ping_at: Date | null;
  missed_count: number;
  last_chance_at: Date | null;
  round: number;
  released_at: Date | null;
  updated_at: Date;
};

export async function getVault(slug: string): Promise<Vault | null> {
  const [v] = await sql<Vault[]>`select id, slug, owner_name, is_demo from vaults where slug = ${slug}`;
  return v ?? null;
}

export async function getVaultById(id: string): Promise<Vault | null> {
  const [v] = await sql<Vault[]>`select id, slug, owner_name, is_demo from vaults where id = ${id}`;
  return v ?? null;
}

export async function getPeople(vaultId: string): Promise<Person[]> {
  return sql<Person[]>`select id, vault_id, role, name, relation, email, auth0_sub from people where vault_id = ${vaultId} order by role, name`;
}

export async function getPerson(id: string): Promise<Person | null> {
  const [p] = await sql<Person[]>`select id, vault_id, role, name, relation, email, auth0_sub from people where id = ${id}`;
  return p ?? null;
}

export async function getSwitch(vaultId: string): Promise<SwitchRow> {
  const [s] = await sql<SwitchRow[]>`select * from switch where vault_id = ${vaultId}`;
  return s;
}

// Links a signed-in Auth0 user to their person row (by verified email) the first time they sign in.
export async function personForSession(user: { sub: string; email?: string | null; email_verified?: boolean }): Promise<Person[]> {
  if (user.email && user.email_verified) {
    await sql`update people set auth0_sub = ${user.sub} where lower(email) = lower(${user.email}) and auth0_sub is null`;
  }
  return sql<Person[]>`select id, vault_id, role, name, relation, email, auth0_sub from people where auth0_sub = ${user.sub}`;
}
// Creating and filling a vault: used by the seed script and the owner's editor.
import { sql } from "./db";
import { embed, toVector } from "./embed";
import { shareLetter, shareNote } from "./fga";

export async function addNote(vaultId: string, note: { title: string; body: string; sharedWith: string[]; source?: string }) {
  const vec = toVector(await embed(`${note.title}\n${note.body}`));
  const [row] = await sql`
    insert into notes (vault_id, title, body, shared_with, embedding, source)
    values (${vaultId}, ${note.title}, ${note.body}, ${note.sharedWith}::uuid[], ${vec}::vector, ${note.source ?? "owner"})
    returning id`;
  await shareNote(vaultId, row.id, note.sharedWith);
  return row.id as string;
}

export async function updateNote(vaultId: string, id: string, note: { title: string; body: string; sharedWith: string[] }) {
  const [old] = await sql`select shared_with from notes where id = ${id} and vault_id = ${vaultId}`;
  if (!old) throw new Error("no such note");
  const vec = toVector(await embed(`${note.title}\n${note.body}`));
  await sql`
    update notes set title = ${note.title}, body = ${note.body}, shared_with = ${note.sharedWith}::uuid[],
      embedding = ${vec}::vector, updated_at = now()
    where id = ${id}`;
  await shareNote(vaultId, id, note.sharedWith, old.shared_with);
}

export async function addLetter(vaultId: string, letter: { recipientId: string; title: string; body: string }) {
  const [row] = await sql`
    insert into letters (vault_id, recipient_id, title, body)
    values (${vaultId}, ${letter.recipientId}, ${letter.title}, ${letter.body}) returning id`;
  await shareLetter(vaultId, row.id, letter.recipientId);
  return row.id as string;
}

// Deletes a vault and everything in it. The audit log trigger allows this one path only.
export async function deleteVault(slug: string) {
  await sql.begin(async (tx) => {
    await tx`select set_config('still_here.vault_reset', 'on', true)`;
    await tx`delete from vaults where slug = ${slug}`;
  });
}
// Signed one-tap check-in links, so answering from a phone needs no sign-in.
import { createHmac, timingSafeEqual } from "node:crypto";
import { need } from "./env";

const sign = (payload: string) => createHmac("sha256", need("CHECKIN_SECRET")).update(payload).digest("base64url");

export function checkinToken(vaultId: string, checkinId: string) {
  const payload = `${vaultId}.${checkinId}`;
  return `${payload}.${sign(payload)}`;
}

export function readCheckinToken(token: string): { vaultId: string; checkinId: string } | null {
  const [vaultId, checkinId, mac] = token.split(".");
  if (!vaultId || !checkinId || !mac) return null;
  const expected = Buffer.from(sign(`${vaultId}.${checkinId}`));
  const given = Buffer.from(mac);
  if (expected.length !== given.length || !timingSafeEqual(expected, given)) return null;
  return { vaultId, checkinId };
}
