  --line: #3a3029;
  --text: #f0e7d8;
  --soft: #ab9c88;
  --marigold: #eaa33a; /* the one accent; the tints below are the same hue */
  --marigold-deep: #c47a1c;
  --marigold-light: #f6c76e;
  --paper: #eee3d1;
  --paper-ink: #2a211b;
  --paper-soft: #5e5246;
  --serif: var(--font-serif), Georgia, serif;
  --sans: var(--font-sans), system-ui, sans-serif;
}
* { box-sizing: border-box; margin: 0; }
