@keyframes rise { from { opacity: 0; transform: translateY(24px); filter: blur(8px); } }
@keyframes beat { 0%,100% { text-shadow: 0 0 0 transparent; } 8% { text-shadow: 0 0 28px rgba(234,163,58,.55); } 20% { text-shadow: 0 0 6px rgba(234,163,58,.15); } 28% { text-shadow: 0 0 22px rgba(234,163,58,.45); } 50% { text-shadow: 0 0 0 transparent; } }
