import { getSwitch } from "./vault";
import { demoReset, tick } from "./switch";

// A released demo stays released for ten minutes, then starts over for the next visitor.
const KEEP_RELEASED_MS = 10 * 60 * 1000;

export async function freshDemoTick(vaultId: string) {
  const s = await getSwitch(vaultId);
  if (s.state === "released" && s.released_at && Date.now() - s.released_at.getTime() > KEEP_RELEASED_MS) await demoReset(vaultId);
  else await tick(vaultId);
}
