"use server";
// Everything the signed-in owner can change. Each action checks the session itself.
import { revalidatePath } from "next/cache";
import { auth0 } from "@/lib/auth0";
import { sql } from "@/lib/db";
import { runHandbook } from "@/lib/handbook";
import { appUrl, push } from "@/lib/ntfy";
import { currentPeople } from "@/lib/session";
import { checkIn } from "@/lib/switch";
import { addLetter, addNote, createVault, deleteNote } from "@/lib/vault-admin";
import { getPeople, getVaultById } from "@/lib/vault";

export type Result = { ok?: string; error?: string } | null;

const text = (f: FormData, k: string, max = 4000) => String(f.get(k) ?? "").trim().slice(0, max);
const isEmail = (s: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);

async function ownerRow() {
  const owner = (await currentPeople()).find((p) => p.role === "owner");
  if (!owner) throw new Error("Only the owner of a vault can do this.");
  return owner;
}

// Wraps an action so a thrown error comes back as a message on the form
const guard = (fn: (f: FormData) => Promise<string>) => async (_: Result, f: FormData): Promise<Result> => {
  try {
    const ok = await fn(f);
    revalidatePath("/me");
    return { ok };
  } catch (e) {
    return { error: (e as Error).message };
  }
};

export const createVaultAction = guard(async (f) => {
  const session = await auth0.getSession();
  if (!session?.user.email) throw new Error("Sign in first.");
  if (!session.user.email_verified) throw new Error("Verify your email with Auth0 first, then sign in again.");
  if ((await currentPeople()).some((p) => p.role === "owner")) throw new Error("You already have a vault.");
  const name = text(f, "name", 60);
  if (!name) throw new Error("Write your name.");
  const trusted = [0, 1, 2]
    .map((i) => ({ name: text(f, `t${i}_name`, 60), relation: text(f, `t${i}_relation`, 40), email: text(f, `t${i}_email`, 200).toLowerCase() }))
    .filter((t) => t.name || t.email);
  if (trusted.length < 2) throw new Error("Name two people you trust. Both must say yes before anything opens.");
  for (const t of trusted) {
    if (!t.name || !isEmail(t.email)) throw new Error("Each trusted person needs a name and an email.");
    if (t.email === session.user.email.toLowerCase()) throw new Error("You can't be your own trusted person.");
  }
  if (new Set(trusted.map((t) => t.email)).size !== trusted.length) throw new Error("Use a different email for each person.");
  await createVault({ name, email: session.user.email, sub: session.user.sub }, trusted);
  return "Vault created.";
});

export const checkInAction = guard(async (f) => {
  const owner = await ownerRow();
  const r = await checkIn(owner.vault_id, { line: text(f, "line", 500), channel: "web" });
  if (!r.ok) throw new Error("This vault has been released. It can't be undone from here.");
  return r.was === "alive" ? "Answered. See you next week." : "Answered. The switch is back to alive.";
});

export const testPushAction = guard(async () => {
  const owner = await ownerRow();
  const vault = await getVaultById(owner.vault_id);
  const sent = await push({ topic: vault?.ntfy_topic, title: "Still Here: test", message: "This is how the weekly question will arrive.", click: appUrl("/me"), priority: 3 });
  if (!sent) throw new Error("ntfy did not accept the push. Try again in a minute.");
  return "Sent. Check your phone.";
});

export const addNoteAction = guard(async (f) => {
  const owner = await ownerRow();
  const title = text(f, "title", 120), body = text(f, "body", 4000);
  if (!title || !body) throw new Error("A note needs a title and some text.");
  const [{ n }] = await sql`select count(*)::int as n from notes where vault_id = ${owner.vault_id}`;
  if (n >= 200) throw new Error("A vault holds up to 200 notes.");
  const people = (await getPeople(owner.vault_id)).filter((p) => p.role === "trusted");
  const shared = f.getAll("shared").map(String).filter((id) => people.some((p) => p.id === id));
  await addNote(owner.vault_id, { title, body, sharedWith: shared });
  return shared.length ? "Saved. Only the people you ticked can ever ask about it." : "Saved. Nobody can ask about it: it is shared with no one.";
});

export const deleteNoteAction = guard(async (f) => {
  const owner = await ownerRow();
  await deleteNote(owner.vault_id, text(f, "id", 64));
  return "Deleted.";
});

export const addLetterAction = guard(async (f) => {
  const owner = await ownerRow();
  const to = text(f, "to", 64), body = text(f, "body", 8000);
  const person = (await getPeople(owner.vault_id)).find((p) => p.id === to && p.role === "trusted");
  if (!person) throw new Error("Pick who the letter is for.");
  if (!body) throw new Error("Write the letter first.");
  await addLetter(owner.vault_id, { recipientId: person.id, title: `For ${person.name}`, body });
  return `Sealed. ${person.name} can read it only after release.`;
});

export const deleteLetterAction = guard(async (f) => {
  const owner = await ownerRow();
  await sql`delete from letters where id = ${text(f, "id", 64)} and vault_id = ${owner.vault_id}`;
  return "Deleted.";
});

export const addDocumentAction = guard(async (f) => {
  const owner = await ownerRow();
  const title = text(f, "title", 160), body = text(f, "body", 6000);
  const kind = ["policy", "statement", "subscription", "other"].includes(text(f, "kind")) ? text(f, "kind") : "other";
  if (!title || !body) throw new Error("Paste the document text and give it a title.");
  const [{ n }] = await sql`select count(*)::int as n from documents where vault_id = ${owner.vault_id}`;
  if (n >= 40) throw new Error("A vault holds up to 40 documents.");
  await sql`insert into documents (vault_id, kind, title, body) values (${owner.vault_id}, ${kind}, ${title}, ${body})`;
  return "Added.";
});

export const deleteDocumentAction = guard(async (f) => {
  const owner = await ownerRow();
  await sql`delete from documents where id = ${text(f, "id", 64)} and vault_id = ${owner.vault_id}`;
  return "Deleted.";
});

export const handbookAction = guard(async () => {
  const owner = await ownerRow();
  const [{ docs }] = await sql`select count(*)::int as docs from documents where vault_id = ${owner.vault_id}`;
  if (!docs) throw new Error("Add at least one document first.");
  const [{ runs }] = await sql`select count(*)::int as runs from handbooks where vault_id = ${owner.vault_id} and created_at > now() - interval '1 day'`;
  if (runs >= 5) throw new Error("Five handbooks a day is the limit. Try again tomorrow.");
  const h = await runHandbook({ vaultId: owner.vault_id, model: "ultramarine-1-flash" });
  const items = h.sections.reduce((n, s) => n + s.items.length, 0);
  return `Written: ${items} lines kept, ${h.dropped.length} dropped for missing sources. Cost $${h.usage.costUsd.toFixed(4)}.`;
});

"use client";
// Forms on the vault page. Each one posts to a server action and shows its result inline.
import { useActionState, useState } from "react";
import { useFormStatus } from "react-dom";
import { HandWaving, LockKey, Note, PaperPlaneRight, Trash } from "@phosphor-icons/react";
import type { AskResult } from "@/lib/ask";
import * as A from "./actions";

type Action = (s: A.Result, f: FormData) => Promise<A.Result>;

function Submit({ children, primary = true }: { children: React.ReactNode; primary?: boolean }) {
  const { pending } = useFormStatus();
  return <button className={`btn ${primary ? "primary" : ""}`} disabled={pending}>{pending ? "Working…" : children}</button>;
}

function Msg({ state }: { state: A.Result }) {
  if (state?.error) return <p className="err" role="alert">{state.error}</p>;
  return <p className="note-msg" aria-live="polite">{state?.ok ?? ""}</p>;
}

function useForm(action: Action) {
  return useActionState(action, null);
}

export function CreateVaultForm({ suggestedName }: { suggestedName: string }) {
  const [state, act] = useForm(A.createVaultAction);
  return (
    <form className="form" action={act}>
      <label>Your name, as your family says it<input className="field" name="name" defaultValue={suggestedName} required maxLength={60} /></label>
      {[0, 1, 2].map((i) => (
        <div className="three" key={i}>
          <label>{i < 2 ? `Trusted person ${i === 0 ? "one" : "two"}` : "A third (optional)"}<input className="field" name={`t${i}_name`} placeholder="Name" required={i < 2} maxLength={60} /></label>
          <label>They are your<input className="field" name={`t${i}_relation`} placeholder={i === 0 ? "sister" : "friend"} maxLength={40} /></label>
          <label>Their email<input className="field" name={`t${i}_email`} type="email" placeholder="they sign in with this" required={i < 2} /></label>
        </div>
      ))}
      <Msg state={state} />
      <div><Submit>Create my vault</Submit></div>
    </form>
  );
}

export function CheckInForm({ disabled }: { disabled: boolean }) {
  const [state, act] = useForm(A.checkInAction);
  return (
    <form action={act}>
      <SubmitYes disabled={disabled} />
      <input className="line" name="line" maxLength={500} placeholder="Anything changed? (moved my FD to SBI)" aria-label="Optional line about what changed" />
      <Msg state={state} />
    </form>
  );
}

function SubmitYes({ disabled }: { disabled: boolean }) {
  const { pending } = useFormStatus();
  return <button className="yes" disabled={disabled || pending}><HandWaving size={20} weight="fill" />I&apos;m still here</button>;
}

export function TestPush() {
  const [state, act] = useForm(A.testPushAction);
  return (
    <form action={act}>
      <Submit primary={false}>Send a test push</Submit>
      <Msg state={state} />
    </form>
  );
}

export function NoteForm({ people }: { people: { id: string; name: string }[] }) {
  const [state, act] = useForm(A.addNoteAction);
  return (
    <form className="form" action={act} key={state?.ok}>
      <label>Title<input className="field" name="title" required maxLength={120} placeholder="LIC life insurance policy" /></label>
      <label>What they need to know<textarea className="field" name="body" required maxLength={4000} placeholder="Policy number, where the paper is, who the nominee is, how to claim." /></label>
      <fieldset className="checks">
        <legend className="sr">Who can ask about this note</legend>
        {people.map((p) => <label key={p.id}><input type="checkbox" name="shared" value={p.id} />{p.name} can ask about this</label>)}
      </fieldset>
      <Msg state={state} />
      <div><Submit><Note size={18} />Save note</Submit></div>
    </form>
  );
}

export function LetterForm({ people }: { people: { id: string; name: string }[] }) {
  const [state, act] = useForm(A.addLetterAction);
  return (
    <form className="form" action={act} key={state?.ok}>
      <label>For<select className="field" name="to" required>{people.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
      <label>The letter<textarea className="field" name="body" required maxLength={8000} rows={8} /></label>
      <Msg state={state} />
      <div><Submit><LockKey size={18} />Seal it</Submit></div>
    </form>
  );
}

export function DocumentForm() {
  const [state, act] = useForm(A.addDocumentAction);
  return (
    <form className="form" action={act} key={state?.ok}>
      <div className="two">
        <label>Title<input className="field" name="title" required maxLength={160} placeholder="Star Health renewal notice" /></label>
        <label>Kind
          <select className="field" name="kind" defaultValue="policy">
            <option value="policy">Policy</option><option value="statement">Statement</option>
            <option value="subscription">Subscription</option><option value="other">Other</option>
          </select>
        </label>
      </div>
      <label>Paste the text<textarea className="field" name="body" required maxLength={6000} /></label>
      <Msg state={state} />
      <div><Submit primary={false}>Add document</Submit></div>
    </form>
  );
}

export function HandbookButton() {
  const [state, act] = useForm(A.handbookAction);
  return (
    <form action={act}>
      <Submit>Write the handbook</Submit>
      <Msg state={state} />
    </form>
  );
}

export function DeleteButton({ action, id, label }: { action: "note" | "letter" | "document"; id: string; label: string }) {
  const fn = { note: A.deleteNoteAction, letter: A.deleteLetterAction, document: A.deleteDocumentAction }[action];
  const [, act] = useForm(fn);
  return (
    <form action={act} className="inline">
      <input type="hidden" name="id" value={id} />
      <button className="link-btn" aria-label={`Delete ${label}`}><Trash size={16} /></button>
    </form>
  );
}

// A trusted person asks the owner's notes after release
export function AskBox({ vaultId, name }: { vaultId: string; name: string }) {
  const [q, setQ] = useState("");
  const [asked, setAsked] = useState("");
  const [res, setRes] = useState<AskResult | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  async function ask(e: React.FormEvent) {
    e.preventDefault();
    if (!q.trim()) return;
    setBusy(true); setErr(""); setRes(null); setAsked(q);
    const r = await fetch("/api/ask", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vaultId, question: q }) });
    const out = await r.json().catch(() => ({}));
    if (r.ok) { setRes(out); setQ(""); } else setErr(out.error ?? "Something went wrong.");
    setBusy(false);
  }

  return (
    <div className="qa" style={{ padding: 0 }}>
      <form className="ask" onSubmit={ask}>
        <label htmlFor="ask-me">Ask {name}&apos;s notes</label>
        <div className="ask-row">
          <input id="ask-me" value={q} onChange={(e) => setQ(e.target.value)} maxLength={300} placeholder="Where is the insurance policy?" />
          <button disabled={busy || !q.trim()} aria-label="Ask"><PaperPlaneRight size={18} /></button>
        </div>
      </form>
      <div className="result" aria-live="polite" style={{ marginTop: 22 }}>
        {asked && <p className="q">You asked: {asked}</p>}
        {busy && <p className="a dim">Reading the notes you are allowed to read…</p>}
        {err && <p className="a dim">{err}</p>}
        {res && (
          <>
            <p className={`a ${res.outcome !== "answered" ? "dim" : ""}`}>{res.answer}</p>
            {res.citations.map((c) => <span key={c.id} className="src"><Note size={15} />{c.title}</span>)}
            <p className="gate"><LockKey size={16} />Search found {res.candidates} notes. FGA let {res.allowed} through for you. The model saw only those.</p>
          </>
        )}
      </div>
    </div>
  );
}

// The signed-in page. The owner manages the vault; a trusted person waits, and after release
// reads their letter and asks the notes they were given.
import { DownloadSimple, EnvelopeSimpleOpen, SignOut } from "@phosphor-icons/react/dist/ssr";
import { End, Top } from "@/components/chrome";
import { auth0 } from "@/lib/auth0";
import { sql } from "@/lib/db";
import { lettersFor } from "@/lib/letters";
import { currentPeople } from "@/lib/session";
import { vaultStatus } from "@/lib/status";
import { getVaultById, type Person } from "@/lib/vault";
import { AskBox, CheckInForm, CreateVaultForm, DeleteButton, DocumentForm, HandbookButton, LetterForm, NoteForm, TestPush } from "./forms";

export const dynamic = "force-dynamic";

const when = (d: Date | string | null) =>
  d ? new Date(d).toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Kolkata" }) : "never";
const days = (s: number) => (s % 86400 === 0 ? `${s / 86400} day${s === 86400 ? "" : "s"}` : `${Math.round(s / 3600)} hours`);

export default async function Me() {
  const session = await auth0.getSession();
  const people = await currentPeople();
  const signOut = (
    <a className="act" href="/auth/logout"><SignOut size={18} />Sign out</a>
  );

  return (
    <>
      <Top short action={signOut} />
      <main className="wrap page">
        {people.length === 0 ? (
          <NoVault name={session?.user.name ?? ""} email={session?.user.email ?? ""} />
        ) : (
          await Promise.all(people.map((p) => (p.role === "owner" ? <Owner key={p.id} me={p} /> : <Trusted key={p.id} me={p} />)))
        )}
        <End />
      </main>
    </>
  );
}

function NoVault({ name, email }: { name: string; email: string }) {
  return (
    <>
      <h1>Start your vault</h1>
      <p className="lede">
        Signed in as {email}. If someone named you as a trusted person, they must use this same email. Otherwise, start your own vault below.
      </p>
      <section className="panel">
        <h2>Who you trust</h2>
        <p className="sub">
          Two people, at least. When you stop answering, each gets an Auth0 Guardian push on their phone, and nothing opens until every one of them
          says yes. They need to sign in here once, with the email you give, so the push can reach them.
        </p>
        <CreateVaultForm suggestedName={name.includes("@") ? "" : name.split(" ")[0]} />
      </section>
    </>
  );
}

async function Owner({ me }: { me: Person }) {
  const [vault, status, notes, letters, documents, handbooks] = await Promise.all([
    getVaultById(me.vault_id),
    vaultStatus(me.vault_id),
    sql`select id, title, body, shared_with from notes where vault_id = ${me.vault_id} order by created_at desc`,
    sql`select id, recipient_id, body, created_at from letters where vault_id = ${me.vault_id} order by created_at`,
    sql`select id, kind, title from documents where vault_id = ${me.vault_id} order by created_at`,
    sql`
      select h.id, h.sections, jsonb_array_length(h.dropped) as dropped, h.created_at, u.cost_usd::float as cost, u.model
      from handbooks h left join usage u on u.id = h.usage_id where h.vault_id = ${me.vault_id} order by h.created_at desc limit 1`,
  ]);
  const sw = status.switch;
  const trusted = status.people.filter((p) => p.role === "trusted");
  const name = (id: string) => trusted.find((p) => p.id === id)?.name ?? "someone";
  const nextPing = new Date(new Date(sw.last_ping_at ?? sw.last_answer_at).getTime() + sw.every_seconds * 1000);
  const handbook = handbooks[0];
  const appUrl = process.env.APP_BASE_URL ?? "";

  return (
    <>
      <h1>Your vault, {me.name}</h1>
      <p className="lede">Nothing here is visible to anyone while you keep answering. The switch below decides when that changes, not a model.</p>

      <div className="state-row">
        <div>
          <p className="state-big">{status.state}</p>
          <dl className="facts">
            <dt>Last answer</dt><dd>{when(sw.last_answer_at)}</dd>
            {status.state === "alive" && (<><dt>Next question</dt><dd>{when(nextPing)}</dd></>)}
            <dt>Missed in a row</dt><dd>{sw.missed_count} of {sw.miss_limit}</dd>
            <dt>Rules</dt><dd>One question every {days(sw.every_seconds)}. After {sw.miss_limit} misses, a last chance and {days(sw.grace_seconds)} to answer.</dd>
          </dl>
        </div>
        <div>
          <CheckInForm disabled={status.state === "released"} />
        </div>
      </div>

      <section className="panel">
        <h2>Your phone</h2>
        <p className="sub">
          The weekly question arrives through ntfy, a free push app with no account. Install it (Android or iPhone), tap +, and subscribe to this topic.
          Keep the name private: anyone with it can read your pushes.
        </p>
        <p style={{ fontSize: 20, marginBottom: 14, wordBreak: "break-all" }}>{vault?.ntfy_topic}</p>
        <TestPush />
      </section>

      <section className="panel">
        <h2>The people you trust</h2>
        <p className="sub">
          Each must sign in once at {appUrl}/me with the email below, and keep Auth0 Guardian on their phone. Until they do, nobody can ask them, and the
          vault waits.
        </p>
        <ul className="list">
          {status.people.filter((p) => p.role === "trusted").map((p) => (
            <li key={p.id}>
              <div><b>{p.name}</b> <small>· {p.relation || "trusted"}</small></div>
              <span className="tag">{p.linked ? "Signed in, can be asked" : "Has not signed in yet"}</span>
            </li>
          ))}
        </ul>
      </section>

      <section className="panel">
        <h2>Notes</h2>
        <p className="sub">
          The facts they will need. After release each person can ask questions, and the model answers only from the notes you shared with them. Auth0 FGA
          checks every note before the model sees it.
        </p>
        <NoteForm people={trusted} />
        {notes.length > 0 && (
          <ul className="list" style={{ marginTop: 14 }}>
            {notes.map((n) => (
              <li key={n.id}>
                <div><b>{n.title}</b><p>{n.body.length > 220 ? `${n.body.slice(0, 220)}…` : n.body}</p></div>
                <div style={{ textAlign: "right" }}>
                  <span className="tag">{n.shared_with.length ? `For ${n.shared_with.map(name).join(", ")}` : "Shared with no one"}</span>
                  <br /><DeleteButton action="note" id={n.id} label={n.title} />
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel">
        <h2>Letters</h2>
        <p className="sub">Each letter opens for one person, and only after release. Nobody, the model included, reads it before then.</p>
        <LetterForm people={trusted} />
        {letters.length > 0 && (
          <ul className="list" style={{ marginTop: 14 }}>
            {letters.map((l) => (
              <li key={l.id}>
                <div><b>For {name(l.recipient_id)}</b><p>{l.body.length > 160 ? `${l.body.slice(0, 160)}…` : l.body}</p></div>
                <DeleteButton action="letter" id={l.id} label={`letter for ${name(l.recipient_id)}`} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel">
        <h2>The handbook</h2>
        <p className="sub">
          Paste the text of policies, statements and renewal emails. Ultramarine drafts what each person needs to do, and code keeps only lines that cite
          one of these documents. You get a Word file to print and keep with your papers.
        </p>
        <DocumentForm />
        {documents.length > 0 && (
          <ul className="list" style={{ margin: "14px 0 20px" }}>
            {documents.map((d) => (
              <li key={d.id}>
                <div><b>{d.title}</b> <small>· {d.kind}</small></div>
                <DeleteButton action="document" id={d.id} label={d.title} />
              </li>
            ))}
          </ul>
        )}
        <HandbookButton />
        {handbook && (
          <p className="sub" style={{ marginTop: 14 }}>
            Last written {when(handbook.created_at)}: {(handbook.sections as { items: unknown[] }[]).reduce((n, s) => n + s.items.length, 0)} lines,{" "}
            {handbook.dropped} dropped, ${Number(handbook.cost ?? 0).toFixed(4)} on {handbook.model}.{" "}
            <a href="/api/handbook"><DownloadSimple size={16} /> Download the .docx</a>
          </p>
        )}
      </section>
    </>
  );
}

async function Trusted({ me }: { me: Person }) {
  const [vault, status] = await Promise.all([getVaultById(me.vault_id), vaultStatus(me.vault_id)]);
  const owner = vault?.owner_name ?? "They";
  const released = status.state === "released";
  const letters = released ? await lettersFor(me.vault_id, me.id) : [];
  const asking = status.state === "confirming" && status.approvals.some((a) => a.person_id === me.id && a.status === "pending");

  return (
    <>
      <h1>{released ? `What ${owner} left you` : `${owner} trusts you`}</h1>
      {!released && (
        <p className="lede">
          {asking
